css:
/* Hallmark · v2.0.0 · theme: Registry (manual deal) · genre: modern-minimal · shape: ledger workbench · signature: ruled ledger rows with aligned tabular amounts · waive: none */
/* critique: density carried by row rhythm and numerals; chrome held to one toolbar; every state named, never dotted. */
:root {
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --paper: #f4f3ef;
  --surface: #ffffff;
  --surface-soft: #faf9f5;
  --surface-hover: #f8f7f2;
  --ink: #1a1c1f;
  --ink-soft: #3f444a;
  --muted: #5a6067;
  --placeholder: #6c7178;
  --line: #d8d6cf;
  --line-soft: #e6e4dd;
  --control-line: #8d9297;
  --clear: transparent;
  --focus: #2e4e7e;
  --primary: #1a1c1f;
  --primary-hover: #31353a;
  --on-primary: #fbfaf7;
  --paid-bg: #e7f1e8;
  --paid-fg: #266044;
  --pending-bg: #f8eeda;
  --pending-fg: #79511a;
  --refunded-bg: #f5e7e4;
  --refunded-fg: #883b33;
  --selection-bg: #dfe7f3;
  --selection-fg: #1a1c1f;
  --radius-control: 5px;
  --radius-surface: 8px;
  --radius-chip: 3px;
  --shell: 1180px;
}
*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; padding: 0; overflow-x: clip; }
html { color-scheme: light; }
body {
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.4;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
::selection { background: var(--selection-bg); color: var(--selection-fg); }
button, input, select { font: inherit; }
button { cursor: pointer; }
button:disabled { cursor: default; }
:where(button, input, select):focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.shell {
  width: 100%;
  max-width: var(--shell);
  margin: 0 auto;
  padding: 0 32px 48px;
}
.masthead {
  position: relative;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 24px 0 14px;
  border-bottom: 2px solid var(--ink);
}
.masthead::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -6px;
  height: 1px;
  background: var(--line);
}
.masthead h1 {
  margin: 0;
  font-size: 28px;
  line-height: 1.15;
  font-weight: 600;
  letter-spacing: -0.025em;
  overflow-wrap: break-word;
  min-width: 0;
}
.masthead .console-label {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 13px;
  white-space: nowrap;
}
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin: 20px 0 14px;
}
.search-field {
  display: flex;
  align-items: center;
  flex: 1 1 300px;
  max-width: 360px;
  height: 38px;
  background: var(--surface);
  border: 1px solid var(--control-line);
  border-radius: var(--radius-control);
  transition: border-color 120ms ease;
}
.search-field:focus-within { border-color: var(--focus); }
.search-field svg {
  flex: none;
  margin: 0 0 0 12px;
  color: var(--muted);
}
.search-field input {
  width: 100%;
  min-width: 0;
  height: 100%;
  padding: 0 12px 0 9px;
  appearance: none;
  -webkit-appearance: none;
  border: 0;
  border-radius: var(--radius-control);
  background: var(--clear);
  color: var(--ink);
  font-size: 15px;
}
.search-field input:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}
.search-field input::placeholder { color: var(--placeholder); opacity: 1; }
.select-wrap {
  position: relative;
  flex: 0 0 168px;
}
.select-wrap select {
  width: 100%;
  height: 38px;
  padding: 0 34px 0 12px;
  appearance: none;
  -webkit-appearance: none;
  background: var(--surface);
  border: 1px solid var(--control-line);
  border-radius: var(--radius-control);
  color: var(--ink);
  font-size: 14px;
  transition: border-color 120ms ease;
}
@media (hover: hover) {
  .search-field:hover:not(:focus-within) { border-color: var(--ink-soft); }
  .select-wrap select:hover { border-color: var(--ink-soft); }
  .quiet-button:hover { background: var(--surface-soft); border-color: var(--ink-soft); }
}
.select-wrap::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 14px;
  width: 7px;
  height: 7px;
  border-right: 1.5px solid var(--muted);
  border-bottom: 1.5px solid var(--muted);
  transform: translateY(-70%) rotate(45deg);
  pointer-events: none;
}
.export-button {
  margin-left: auto;
  height: 38px;
  padding: 0 15px;
  border: 1px solid var(--primary);
  border-radius: var(--radius-control);
  background: var(--primary);
  color: var(--on-primary);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 120ms ease, border-color 120ms ease;
}
@media (hover: hover) {
  .export-button:hover {
    background: var(--primary-hover);
    border-color: var(--primary-hover);
  }
}
.table-surface {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-surface);
  overflow: clip;
}
.orders {
  width: 100%;
  border-collapse: collapse;
  font-size: 15px;
}
.orders th {
  height: 38px;
  padding: 0 16px;
  text-align: left;
  vertical-align: middle;
  background: var(--surface-soft);
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 500;
  letter-spacing: 0;
  white-space: nowrap;
}
.orders th:nth-child(4) { text-align: right; }
.orders td {
  height: 48px;
  padding: 0 16px;
  vertical-align: middle;
  border-top: 1px solid var(--line-soft);
  white-space: nowrap;
}
.orders tbody tr:first-child td { border-top: 0; }
@media (min-width: 721px) {
  .col-order { width: 110px; }
  .col-status { width: 132px; }
  .col-amount { width: 132px; }
  .col-created { width: 136px; }
}
.orders .cell-order {
  color: var(--ink-soft);
  font-size: 13px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.orders .cell-customer {
  color: var(--ink);
  font-weight: 500;
  letter-spacing: -0.005em;
}
.orders .cell-status { text-align: left; }
.orders .cell-amount {
  text-align: right;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.orders .cell-created {
  color: var(--ink-soft);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.chip {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 7px;
  border-radius: var(--radius-chip);
  font-size: 12px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0;
  white-space: nowrap;
}
.chip-paid { background: var(--paid-bg); color: var(--paid-fg); }
.chip-pending { background: var(--pending-bg); color: var(--pending-fg); }
.chip-refunded { background: var(--refunded-bg); color: var(--refunded-fg); }
@media (hover: hover) {
  .orders tbody tr { transition: background-color 120ms ease; }
  .orders tbody tr:hover { background: var(--surface-hover); }
}
.table-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 16px;
  border-top: 1px solid var(--line);
  background: var(--surface-soft);
}
.page-status {
  margin: 0;
  color: var(--muted);
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
}
.pager {
  display: flex;
  align-items: center;
  gap: 4px;
}
.pager button {
  height: 30px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--surface);
  color: var(--ink-soft);
  font-size: 12.5px;
  transition: background-color 120ms ease;
}
.pager button:disabled { color: var(--muted); opacity: 0.55; }
.pager .page-current {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border-radius: 4px;
  background: var(--primary);
  color: var(--on-primary);
  font-size: 12.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
@media (hover: hover) {
  .pager button:not(:disabled):hover { background: var(--surface-soft); }
}
.empty-state { margin-top: 32px; }
.state-label {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 0 9px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
}
.state-label::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--line);
}
.empty-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 148px;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: var(--radius-surface);
  background: var(--surface-soft);
  text-align: center;
}
.empty-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
}
.empty-copy {
  max-width: 46ch;
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 14.5px;
  line-height: 1.5;
}
.quiet-button {
  margin-top: 14px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--control-line);
  border-radius: var(--radius-control);
  background: var(--surface);
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  transition: background-color 120ms ease, border-color 120ms ease;
}
@media (max-width: 720px) {
  .shell { padding: 0 16px 40px; }
  .masthead {
    flex-direction: column;
    align-items: flex-start;
    gap: 3px;
    padding: 20px 0 13px;
  }
  .masthead h1 { font-size: 25px; }
  .masthead .console-label { margin: 0; }
  .toolbar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 10px;
    margin: 18px 0 13px;
  }
  .search-field {
    grid-column: 1 / -1;
    max-width: none;
    flex: none;
  }
  .search-field input,
  .select-wrap select { font-size: 16px; }
  .select-wrap { grid-column: 1; min-width: 0; flex: none; }
  .export-button { grid-column: 2; margin-left: 0; }
  .orders colgroup { display: none; }
  .orders thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
  }
  .orders, .orders tbody { display: block; width: 100%; }
  .orders tbody tr {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    grid-template-areas:
      "order order created"
      "customer status amount";
    gap: 4px 8px;
    padding: 12px 16px;
    border-top: 1px solid var(--line-soft);
  }
  .orders tbody tr:first-child { border-top: 0; }
  .orders tbody tr[hidden] { display: none; }
  .orders td {
    height: auto;
    padding: 0;
    border-top: 0;
    white-space: nowrap;
  }
  .orders .cell-order {
    grid-area: order;
    align-self: center;
    font-size: 12.5px;
  }
  .orders .cell-created {
    grid-area: created;
    justify-self: end;
    align-self: center;
    font-size: 12px;
  }
  .orders .cell-customer {
    grid-area: customer;
    align-self: center;
    min-width: 0;
    white-space: normal;
    overflow-wrap: break-word;
  }
  .orders .cell-status {
    grid-area: status;
    justify-self: start;
    align-self: center;
  }
  .orders .cell-amount {
    grid-area: amount;
    justify-self: end;
    align-self: center;
    font-size: 14px;
  }
  .table-footer { padding: 8px 12px; }
  .pager button { padding: 0 7px; }
}
@media (prefers-reduced-motion: reduce) {
  .search-field,
  .select-wrap select,
  .export-button,
  .orders tbody tr,
  .pager button,
  .quiet-button {
    transition: none;
  }
}
